// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract RevertingToken { fallback() external payable { revert("no"); } }

contract InvMutTest is Test {
    airPort c;
    RevertingToken tok;
    function setUp() public { c = new airPort(); tok = new RevertingToken(); }

    function _run(address from, uint256 v) internal returns (bool reverted) {
        address[] memory tos = new address[](1);
        tos[0] = address(0xBEEF);
        try c.transfer(from, address(tok), tos, v) returns (bool) { reverted = false; } catch { reverted = true; }
    }
    function testFuzz_uncheckedCall(address from, uint256 v) public {
        vm.assume(from != address(0) && from != address(c) && from != address(tok));
        assertTrue(_run(from, v));
    }
}
